    uint256 internal constant ROI_BPS = 3_000;

    // Recycle (red) payout split
    uint256 internal constant RECYCLE_OWNER_BPS = 5_000; // 50 %
    uint256 internal constant RECYCLE_SPONSOR_BPS = 3_000; // 30 %
    uint256 internal constant RECYCLE_SPONSOR2_BPS = 2_000; // 20 %

    // ──────────────────── Enums ────────────────────

    enum PositionType {
        INCOME, // Green  — paid to matrix owner
        RECYCLE, // Red    — split 50/30/20 + recycle buffer
        AUTO_UPGRADE, // Yellow — added to upgrade buffer
        ROYAL_CLUB // Blue   — routed to Royal Club pools
    }

    // ──────────────────── Rank prices (18-decimal BTCB) ────────────────────
    // P[r+1] = P[r] × 2.1   (exact integer: × 21 / 10)

    function getRankPrice(uint8 rank) internal pure returns (uint256) {
        if (rank == 1) return 500_000_000_000_000;
        if (rank == 2) return 1_050_000_000_000_000;
        if (rank == 3) return 2_205_000_000_000_000;
        if (rank == 4) return 4_630_500_000_000_000;
        if (rank == 5) return 9_724_050_000_000_000;
        if (rank == 6) return 20_420_505_000_000_000;
        if (rank == 7) return 42_883_060_500_000_000;
        if (rank == 8) return 90_054_427_050_000_000;
        if (rank == 9) return 189_114_296_805_000_000;
        if (rank == 10) return 397_140_023_290_500_000;
        if (rank == 11) return 833_994_048_910_050_000;
        if (rank == 12) return 1_751_387_502_711_105_000;
        revert("MatrixLib: invalid rank");
    }

    /// @notice Matrix portion = 70 % of rank price
    function getMatrixAmount(uint8 rank) internal pure returns (uint256) {
        return getRankPrice(rank) * 7 / 10;
    }

    /// @notice ROI portion = 30 % of rank price
    function getROIAmount(uint8 rank) internal pure returns (uint256) {
        return getRankPrice(rank) * 3 / 10;
    }

    // ──────────────────── Position type map ────────────────────

    /**
     * @notice Determine the type of a matrix position.
     * @param position 1-based position index (1..39)
     * @param cycle    Cycle number (1 = first cycle, 2+ = subsequent)
     */
    function getPositionType(uint8 position, uint32 cycle) internal pure returns (PositionType) {
        require(position >= 1 && position <= MATRIX_SIZE, "MatrixLib: invalid position");

        // Red positions — all cycles
        if (position == 3 || position == 12 || position == 39) {
            return PositionType.RECYCLE;
        }

        // Cycle 1: positions 13,14,19,20,30,31 are yellow
        if (cycle == 1) {
            if (
                position == 13 || position == 14 || position == 19 || position == 20 || position == 30
                    || position == 31
            ) {
                return PositionType.AUTO_UPGRADE;
            }
            return PositionType.INCOME;
        }

        // Cycle 2+: 13,14 become blue (Royal Club)
        if (position == 13 || position == 14) {
            return PositionType.ROYAL_CLUB;
        }

        // Cycle 2+: 19,20,30,31 remain yellow
        if (position == 19 || position == 20 || position == 30 || position == 31) {
            return PositionType.AUTO_UPGRADE;
        }

        return PositionType.INCOME;
    }

    // ──────────────────── Line percentage ────────────────────

    /// @return Percentage in basis points (2000 = 20 %, 3000 = 30 %, 5000 = 50 %)
    function getLinePercentage(uint8 position) internal pure returns (uint256) {
        require(position >= 1 && position <= MATRIX_SIZE, "MatrixLib: invalid position");
        if (position <= 3) return 2_000; // Line 1 — 20 %
        if (position <= 12) return 3_000; // Line 2 — 30 %
        return 5_000; // Line 3 — 50 %
    }

    // ──────────────────── Payout calculation ────────────────────

    /// @notice Payout = M[rank] × linePercent / 10 000
    function getPayoutAmount(uint8 rank, uint8 position) internal pure returns (uint256) {
        return getMatrixAmount(rank) * getLinePercentage(position) / BASIS_POINTS;
    }

    // ──────────────────── Tree navigation ────────────────────

    /// @notice Parent of a position (0 = root / matrix owner)
    function getParent(uint8 position) internal pure returns (uint8) {
        require(position >= 1 && position <= MATRIX_SIZE, "MatrixLib: invalid position");
        if (position <= 3) return 0; // children of root
        if (position <= 12) return uint8((position - 1) / 3); // Line 2
        return uint8((position - 13) / 3 + 4); // Line 3
    }

    /// @notice Children of a position. Returns [0,0,0] for leaf nodes (Line 3).
    function getChildren(uint8 position) internal pure returns (uint8[3] memory) {
        if (position == 0) return [uint8(1), uint8(2), uint8(3)];
        if (position >= 1 && position <= 3) {
            uint8 s = 4 + (position - 1) * 3;
            return [s, s + 1, s + 2];
        }
        if (position >= 4 && position <= 12) {
            uint8 s = 13 + (position - 4) * 3;
            return [s, s + 1, s + 2];
        }
        return [uint8(0), uint8(0), uint8(0)];
    }

    /// @notice True if `position` is a Line-3 leaf (no children).
    function isLeaf(uint8 position) internal pure returns (bool) {
        return position >= 13 && position <= MATRIX_SIZE;
    }
}

