// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ROILib
 * @notice Manages time-based ROI deposits (the "Arbitrage" program).
 *         Each deposit accrues 3.34 % daily for up to 90 days (≈ 300.6 % total).
 */
library ROILib {
    // ──────────────────── Constants ────────────────────

    uint256 internal constant DAILY_RATE_BPS = 334; // 3.34 %
    uint256 internal constant MAX_DAYS = 120;
    uint256 internal constant BASIS_POINTS = 10_000;
    // uint256 internal constant SECONDS_PER_DAY = 86_400;
    uint256 internal constant SECONDS_PER_DAY = 10;

    // ──────────────────── Structs ────────────────────

    struct Deposit {
        uint256 principal;
        uint256 startTime;
        uint256 claimedDays;
        uint8 rank;
        bool active;
    }

    struct ROIState {
        mapping(address => Deposit[]) deposits;
    }

    // ──────────────────── Functions ────────────────────

    /// @notice Create a new ROI deposit for `user`.
    function createDeposit(ROIState storage self, address user, uint256 amount, uint8 rank) internal {
        self.deposits[user].push(
            Deposit({principal: amount, startTime: block.timestamp, claimedDays: 0, rank: rank, active: true})
        );
    }

    /// @notice View: total unclaimed ROI across all deposits.
    function getPendingROI(ROIState storage self, address user) internal view returns (uint256 total) {
        Deposit[] storage deps = self.deposits[user];
        for (uint256 i = 0; i < deps.length; i++) {
            if (!deps[i].active) continue;

            uint256 elapsed = _elapsedDays(deps[i].startTime);
            if (elapsed > MAX_DAYS) elapsed = MAX_DAYS;

            uint256 claimable = elapsed - deps[i].claimedDays;
            if (claimable > 0) {
                total += deps[i].principal * DAILY_RATE_BPS * claimable / BASIS_POINTS;
            }
        }
    }

    /**
     * @notice Claim all accrued ROI for `user`.
     * @dev Reverts if nothing to claim or if the contract doesn't hold enough BTCB.
     * @return total The amount to transfer to the user.
     */
    function claimROI(ROIState storage self, address user, uint256 contractBalance)
        internal
        returns (uint256 total)
    {
        total = 0;
        Deposit[] storage deps = self.deposits[user];

        for (uint256 i = 0; i < deps.length; i++) {
            if (!deps[i].active) continue;

            uint256 elapsed = _elapsedDays(deps[i].startTime);
            if (elapsed > MAX_DAYS) elapsed = MAX_DAYS;

            uint256 claimable = elapsed - deps[i].claimedDays;
            if (claimable > 0) {
                total += deps[i].principal * DAILY_RATE_BPS * claimable / BASIS_POINTS;
                deps[i].claimedDays = elapsed;

                if (elapsed >= MAX_DAYS) {
                    deps[i].active = false;
                }
            }
        }

        require(total > 0, "ROILib: nothing to claim");
        require(contractBalance >= total, "ROILib: insufficient balance");
    }

    /// @notice Number of deposits held by `user`.
    function getDepositCount(ROIState storage self, address user) internal view returns (uint256) {
        return self.deposits[user].length;
    }

    /**
     * @notice View: per-deposit detail for the UI earnings breakdown.
     */
    function getDepositDetails(ROIState storage self, address user)
        internal
        view
        returns (
            uint256[] memory principals,
            uint256[] memory startTimes,
            uint256[] memory claimedDaysArr,
            uint256[] memory daysElapsedArr,
            uint256[] memory daysRemainingArr,
            uint256[] memory pendingPerDeposit,
            uint8[]   memory ranks,
            bool[]    memory activeArr
        )
    {
        Deposit[] storage deps = self.deposits[user];
        uint256 n = deps.length;
        principals        = new uint256[](n);
        startTimes        = new uint256[](n);
        claimedDaysArr    = new uint256[](n);
        daysElapsedArr    = new uint256[](n);
        daysRemainingArr  = new uint256[](n);
        pendingPerDeposit = new uint256[](n);
        ranks             = new uint8[](n);
        activeArr         = new bool[](n);

        for (uint256 i = 0; i < n; i++) {
            Deposit storage d = deps[i];
            uint256 elapsed = _elapsedDays(d.startTime);
            if (elapsed > MAX_DAYS) elapsed = MAX_DAYS;
            uint256 claimable = elapsed > d.claimedDays ? elapsed - d.claimedDays : 0;

            principals[i]        = d.principal;
            startTimes[i]        = d.startTime;
            claimedDaysArr[i]    = d.claimedDays;
            daysElapsedArr[i]    = elapsed;
            daysRemainingArr[i]  = MAX_DAYS > d.claimedDays ? MAX_DAYS - d.claimedDays : 0;
            pendingPerDeposit[i] = claimable > 0
                ? d.principal * DAILY_RATE_BPS * claimable / BASIS_POINTS
                : 0;
            ranks[i]             = d.rank;
            activeArr[i]         = d.active;
        }
    }

    // ──────────────────── Helpers ────────────────────

    function _elapsedDays(uint256 startTime) private view returns (uint256) {
        if (block.timestamp <= startTime) return 0;
        return (block.timestamp - startTime) / SECONDS_PER_DAY;
    }
}

