// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title RoyalClubLib
 * @notice Manages the 4-tier Royal Club global passive reward pools.
 *         Uses a dividend-per-share model for gas-safe, claim-based distribution.
 *
 *   Tier 1 (BTC Club)              — 10 % — requires ≥ 3 active ranks
 *   Tier 2 (BTC Royal Club)        — 20 % — requires ≥ 6 active ranks
 *   Tier 3 (BTC Royal Millionaire) — 30 % — requires ≥ 9 active ranks
 *   Tier 4 (BTC Royal Ambassador)  — 40 % — requires  12 active ranks
 */
library RoyalClubLib {
    // ──────────────────── Constants ────────────────────

    uint256 internal constant TIER_COUNT = 4;
    uint256 internal constant BASIS_POINTS = 10_000;
    uint256 internal constant ACC_PRECISION = 1e18;

    // Allocation basis points per tier (must sum to 10 000)
    uint256 internal constant TIER1_ALLOC = 2_500; // 10 %
    uint256 internal constant TIER2_ALLOC = 2_500; // 20 %
    uint256 internal constant TIER3_ALLOC = 2_500; // 30 %
    uint256 internal constant TIER4_ALLOC = 2_500; // 40 %

    // Minimum active ranks to qualify for each tier
    uint8 internal constant TIER1_THRESHOLD = 3;
    uint8 internal constant TIER2_THRESHOLD = 6;
    uint8 internal constant TIER3_THRESHOLD = 9;
    uint8 internal constant TIER4_THRESHOLD = 12;

    // ──────────────────── Structs ────────────────────

    struct TierData {
        uint256 accRewardPerUser; // scaled by ACC_PRECISION
        uint256 qualifierCount;
        uint256 pendingFunds; // parked when 0 qualifiers
    }

    struct UserTierData {
        bool qualified;
        uint256 rewardDebt; // scaled by ACC_PRECISION
    }

    struct RoyalClubState {
        TierData[4] tiers;
        mapping(address => UserTierData[4]) userTiers;
    }

    // ──────────────────── Core functions ────────────────────

    /// @notice Route `amount` from a blue position into the 4 tier pools (10/20/30/40).
    function fundPool(RoyalClubState storage self, uint256 amount) internal {
        uint256[4] memory allocs;
        allocs[0] = amount * TIER1_ALLOC / BASIS_POINTS;
        allocs[1] = amount * TIER2_ALLOC / BASIS_POINTS;
        allocs[2] = amount * TIER3_ALLOC / BASIS_POINTS;
        allocs[3] = amount * TIER4_ALLOC / BASIS_POINTS;

        for (uint256 i = 0; i < TIER_COUNT; i++) {
            if (self.tiers[i].qualifierCount > 0) {
                self.tiers[i].accRewardPerUser += allocs[i] * ACC_PRECISION / self.tiers[i].qualifierCount;
            } else {
                self.tiers[i].pendingFunds += allocs[i];
            }
        }
    }

    /**
     * @notice Update tier qualifications for `user` based on their active rank count.
     *         Once qualified, a user never loses qualification (ranks only go up).
     */
    function updateQualification(RoyalClubState storage self, address user, uint8 activeRankCount) internal {
        uint8[4] memory thresholds = [TIER1_THRESHOLD, TIER2_THRESHOLD, TIER3_THRESHOLD, TIER4_THRESHOLD];

        for (uint256 i = 0; i < TIER_COUNT; i++) {
            bool shouldQualify = activeRankCount >= thresholds[i];
            UserTierData storage utd = self.userTiers[user][i];

            if (shouldQualify && !utd.qualified) {
                utd.qualified = true;
                self.tiers[i].qualifierCount++;
                // Set debt so user doesn't earn retroactive rewards
                utd.rewardDebt = self.tiers[i].accRewardPerUser;

                // Flush any funds that were parked while tier had 0 qualifiers
                if (self.tiers[i].pendingFunds > 0) {
                    self.tiers[i].accRewardPerUser +=
                        self.tiers[i].pendingFunds * ACC_PRECISION / self.tiers[i].qualifierCount;
                    self.tiers[i].pendingFunds = 0;
                }
            }
        }
    }

    /// @notice Claim all accrued Royal Club rewards. Reverts if nothing to claim.
    function claimRoyalClub(RoyalClubState storage self, address user) internal returns (uint256 total) {
        total = 0;

        for (uint256 i = 0; i < TIER_COUNT; i++) {
            UserTierData storage utd = self.userTiers[user][i];
            if (!utd.qualified) continue;

            uint256 pending = (self.tiers[i].accRewardPerUser - utd.rewardDebt) / ACC_PRECISION;
            if (pending > 0) {
                total += pending;
                utd.rewardDebt = self.tiers[i].accRewardPerUser;
            }
        }

        require(total > 0, "RoyalClubLib: nothing to claim");
    }

    /// @notice View: total unclaimed Royal Club rewards for `user`.
    function getPendingRoyalClub(RoyalClubState storage self, address user) internal view returns (uint256 total) {
        total = 0;
        for (uint256 i = 0; i < TIER_COUNT; i++) {
            UserTierData storage utd = self.userTiers[user][i];
            if (!utd.qualified) continue;
            total += (self.tiers[i].accRewardPerUser - utd.rewardDebt) / ACC_PRECISION;
        }
    }

    /**
     * @notice View: per-tier qualification status and pending rewards for `user`.
     */
    function getTierStatus(RoyalClubState storage self, address user)
        internal
        view
        returns (
            bool[4]    memory qualified,
            uint256[4] memory pendingPerTier,
            uint256[4] memory qualifierCounts,
            uint256[4] memory poolShares      // basis-points: 1000/2000/3000/4000
        )
    {
        uint256[4] memory allocs = [TIER1_ALLOC, TIER2_ALLOC, TIER3_ALLOC, TIER4_ALLOC];
        for (uint256 i = 0; i < TIER_COUNT; i++) {
            UserTierData storage utd = self.userTiers[user][i];
            qualified[i]       = utd.qualified;
            qualifierCounts[i] = self.tiers[i].qualifierCount;
            poolShares[i]      = allocs[i];
            if (utd.qualified) {
                pendingPerTier[i] =
                    (self.tiers[i].accRewardPerUser - utd.rewardDebt) / ACC_PRECISION;
            }
        }
    }
}

