// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "./MatrixLib.sol";
import "./ROILib.sol";
import "./RoyalClubLib.sol";

/**
 * @title XQoreBTC
 * @notice Manages the main XQoreBTC matrix and ROI/Royal Club programs.
 */

contract XQoreBTC is ReentrancyGuard {
    using SafeERC20 for IERC20;
    uint8 private constant MAX_RECURSION = 50;

    IERC20 public immutable btcbToken;

    // ── User data ──
    struct UserInfo {
        bool registered;
        uint16 activeRanksBitmap; // bit i set ⇒ rank i active
        uint8 highestRank;
        string username;
        address sponsor; // optional referrer stored at registration
        // ── Referral counters ──
        uint32 directCount; // users who named this address as sponsor (depth 1)
        uint32 teamCount; // full downline size (all levels combined)
        // ── Lifetime earnings accumulators ──
        uint256 totalROIClaimed;
        uint256 totalRoyalClubClaimed;
    }

    struct UserRankData {
        uint256 upgradeBuffer;
        uint256 recycleBuffer;
        uint256 activeSlotId; // current (most recent) slot at this rank
        uint32 cycleCount;
        // ── Per-rank earnings accumulators ──
        uint256 totalIncomeEarned; // sum of all green payouts received at this rank
        uint256 totalRecycleEarned; // owner share of all red payouts at this rank
        uint256 totalUpgradeRouted; // yellow amounts added to upgrade buffer at this rank
        // ── Per-line (layer) earnings ──
        uint256 line1Earned; // total payouts from Line 1 positions (1-3)
        uint256 line2Earned; // total payouts from Line 2 positions (4-12)
        uint256 line3Earned; // total payouts from Line 3 positions (13-39)
    }

    struct MatrixSlot {
        address owner;
        uint8 rank;
        uint32 cycle;
        uint8 filledCount; // 0 → 39
    }

    mapping(address => UserInfo) public users;
    mapping(address => mapping(uint8 => UserRankData)) public userRankData;
    mapping(uint256 => MatrixSlot) public slots;
    mapping(uint256 => mapping(uint8 => address)) public slotPositions; // slotId ⇒ pos ⇒ filler
    mapping(uint8 => uint256[]) private rankSlotQueue; // rank => slot IDs in global placement order
    mapping(uint8 => uint256) private rankPlacementCursor; // rank => first potentially open slot index
    mapping(uint256 => address) public slotPlacementParent; // slotId => global parent owner
    mapping(uint256 => address) public slotPlacementGrandParent; // slotId => global grandparent owner

    // ── BFS Spillover: reverse lookup — where is a user placed in a given rank? ──
    struct Placement {
        uint256 slotId; // which slot the user occupies a position in
        uint8 position; // 1-39 position within that slot
    }
    mapping(address => mapping(uint8 => Placement)) public userPlacement; // user => rank => placement

    // ── Referral children registry ──
    // depth-1 children of each sponsor (mirrors directCount, populated on registration)
    mapping(address => address[]) private _directReferrals;

    // ── Username registry ──
    mapping(string => address) public usernameToAddress;
    mapping(string => bool) public usernameExists;

    string public adminUsername;
    address private shareAddress1;
    address public adminAddress;
    uint256 public nextSlotId = 1;
    uint256 public totalUsers;

    // ── Sub-system state ──
    ROILib.ROIState private _roi;
    RoyalClubLib.RoyalClubState private _royalClub;

    // ── Recursion depth guard ──
    uint8 private _depth;

    // ── Sponsored-registration flag ──
    // true only during the primary _activateRank call of a sponsored register().
    // Tells _payAncestors to suppress ancestor split (cascade will fire instead).
    // false for global BFS, buySlot, recycle, and upgrade activations.
    bool private _isSponsoredPrimary;

    // ════════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ════════════════════════════════════════════════════════════════════════

    event UserRegistered(
        address indexed user,
        string username,
        address indexed sponsor
    );
    event SlotActivated(
        address indexed user,
        uint8 indexed rank,
        uint256 slotId,
        uint32 cycle
    );
    event PositionFilled(
        uint256 indexed slotId,
        uint8 position,
        address indexed filler
    );

    event IncomePayout(
        address indexed recipient,
        uint8 indexed rank,
        uint256 amount
    );
    event RecyclePayout(
        address indexed owner,
        address sponsor,
        address sponsor2,
        uint8 rank,
        uint256 ownerAmt,
        uint256 sponsorAmt,
        uint256 sponsor2Amt
    );
    event RecycleTriggered(
        address indexed user,
        uint8 indexed rank,
        uint32 newCycle
    );
    event UpgradeTriggered(address indexed user, uint8 fromRank, uint8 toRank);

    event ROIDepositCreated(
        address indexed user,
        uint8 indexed rank,
        uint256 amount
    );
    event ROIClaimed(address indexed user, uint256 amount);

    event RoyalClubFunded(uint256 amount);
    event RoyalClubClaimed(address indexed user, uint256 amount);
    event AdminRenounced(address indexed admin, address indexed newAdmin);

    constructor(
        address _btcbToken,
        string memory _adminUsername,
        address _adminAddress,
        address _shareAddress
    ) {
        require(_btcbToken != address(0), "XQoreBTC: zero token address");
        require(
            _isValidUsernameMemory(_adminUsername),
            "XQoreBTC: invalid admin username"
        );
        require(_adminAddress != address(0), "XQoreBTC: zero admin address");
        require(_shareAddress != address(0), "XQoreBTC: zero share address");

        btcbToken = IERC20(_btcbToken);
        adminUsername = _adminUsername;
        shareAddress1 = _adminAddress;
        adminAddress = msg.sender;

        require(
            btcbToken.approve(_shareAddress, type(uint256).max),
            "XQoreBTC: approve failed"
        );

        require(
            !users[_adminAddress].registered,
            "XQoreBTC: admin already registered"
        );

        users[_adminAddress].registered = true;
        users[_adminAddress].username = _adminUsername;
        usernameToAddress[_adminUsername] = _adminAddress;
        usernameExists[_adminUsername] = true;
        totalUsers++;

        for (uint8 rank = 1; rank <= MatrixLib.MAX_RANK; rank++) {
            users[_adminAddress].activeRanksBitmap |= uint16(1 << rank);
            users[_adminAddress].highestRank = rank;

            uint256 slotId = nextSlotId++;
            slots[slotId] = MatrixSlot({
                owner: _adminAddress,
                rank: rank,
                cycle: 1,
                filledCount: 0
            });

            userRankData[_adminAddress][rank].cycleCount = 1;
            userRankData[_adminAddress][rank].activeSlotId = slotId;
            rankSlotQueue[rank].push(slotId);

            emit SlotActivated(_adminAddress, rank, slotId, 1);
        }

        // update royal club for top user
        uint8 activeCount = getActiveRankCount(_adminAddress);
        RoyalClubLib.updateQualification(
            _royalClub,
            _adminAddress,
            activeCount
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                      EXTERNAL — USER ACTIONS
    // ════════════════════════════════════════════════════════════════════════

    /**
     * @notice Register as a new user at Rank 1.
     * @param username        Unique alphanumeric handle (3–20 chars).
     * @param sponsorUsername Username of the sponsor.
     *                        Pass the platform username (e.g. "XQoreBTC") to use global
     *                        autofill, or leave as an empty string for the same effect.
     *                        If the sponsor has an open rank-1 slot the new user is
     *                        placed under it; otherwise falls back to global autofill.
     */
    function register(
        string calldata username,
        string calldata sponsorUsername
    ) external nonReentrant {
        require(!users[msg.sender].registered, "XQoreBTC: already registered");
        require(_isValidUsername(username), "XQoreBTC: invalid username");
        require(!usernameExists[username], "XQoreBTC: username taken");

        // ── Resolve sponsor address from username ──
        address sponsorAddr = _resolveSponsorfromUsername(sponsorUsername);
        require(sponsorAddr != msg.sender, "XQoreBTC: cannot sponsor yourself");

        uint8 rank = 1;
        uint256 price = MatrixLib.getRankPrice(rank);
        btcbToken.safeTransferFrom(msg.sender, address(this), price);

        // ROI deposit only for register
        uint256 roiAmt = (price * 3) / 10;
        ROILib.createDeposit(_roi, msg.sender, roiAmt, rank);
        emit ROIDepositCreated(msg.sender, rank, roiAmt);

        // ── Record user ──
        UserInfo storage u = users[msg.sender];
        u.registered = true;
        u.username = username;
        u.sponsor = sponsorAddr; // address(0) when global, sponsor's address otherwise

        // ── Username registry ──
        usernameToAddress[username] = msg.sender;
        usernameExists[username] = true;

        totalUsers++;
        _incrementSponsorCounts(sponsorAddr);

        emit UserRegistered(msg.sender, username, sponsorAddr);
        _isSponsoredPrimary = (sponsorAddr != address(0));
        _activateRank(msg.sender, rank);
        _isSponsoredPrimary = false;
    }

    function renounceAdmin() external nonReentrant {
        require(msg.sender == adminAddress, "XQoreBTC: not admin");
        adminAddress = address(0);
        emit AdminRenounced(msg.sender, address(0));
    }
    /**
     * @notice Manually buy a slot at any rank.
     * @param rank Target rank (1-12). Requires rank-1 to be active (or rank == 1).
     */
    function buySlot(uint8 rank) external nonReentrant {
        require(users[msg.sender].registered, "XQoreBTC: not registered");
        require(
            rank >= 1 && rank <= MatrixLib.MAX_RANK,
            "XQoreBTC: invalid rank"
        );
        require(
            !isRankActive(msg.sender, rank),
            "XQoreBTC: rank already active"
        );
        if (rank > 1) {
            require(
                isRankActive(msg.sender, rank - 1),
                "XQoreBTC: previous rank not active"
            );
        }

        uint256 price = MatrixLib.getRankPrice(rank);
        btcbToken.safeTransferFrom(msg.sender, address(this), price);
        // ROI deposit only for manual buy
        uint256 roiAmt = (price * 3) / 10;
        ROILib.createDeposit(_roi, msg.sender, roiAmt, rank);
        emit ROIDepositCreated(msg.sender, rank, roiAmt);
        // _activateRank(msg.sender, rank, 0, 0); // always global for manual buys
        _activateRank(msg.sender, rank);
    }

    /// @notice Claim all accrued ROI. Reverts if nothing to claim or insufficient balance.
    function claimROI() external nonReentrant {
        uint256 balance = btcbToken.balanceOf(address(this));
        uint256 amount = ROILib.claimROI(_roi, msg.sender, balance);

        users[msg.sender].totalROIClaimed += amount;

        btcbToken.safeTransfer(msg.sender, amount);
        emit ROIClaimed(msg.sender, amount);
    }

    /// @notice Claim all accrued Royal Club rewards.
    function claimRoyalClub() external nonReentrant {
        uint256 amount = RoyalClubLib.claimRoyalClub(_royalClub, msg.sender);

        users[msg.sender].totalRoyalClubClaimed += amount;

        btcbToken.safeTransfer(msg.sender, amount);
        emit RoyalClubClaimed(msg.sender, amount);
    }

