    function _recycleSlot(address user, uint8 rank) internal {
        UserRankData storage urd = userRankData[user][rank];

        if (users[user].sponsor == address(0)) {
            urd.cycleCount++;

            uint256 slotId = nextSlotId++;
            slots[slotId] = MatrixSlot({
                owner: user,
                rank: rank,
                cycle: urd.cycleCount,
                filledCount: 0
            });

            urd.activeSlotId = slotId;
            rankSlotQueue[rank].push(slotId);

            emit SlotActivated(user, rank, slotId, urd.cycleCount);
            return;
        }

        bool savedFlag = _isSponsoredPrimary;
        _isSponsoredPrimary = false;

        (
            uint256 sponsorTargetSlot,
            uint8 sponsorSubtreeRoot
        ) = _resolveSponsorSlot(users[user].sponsor, rank);

        _createAndPlaceSlot(user, rank, sponsorTargetSlot, sponsorSubtreeRoot);

        _isSponsoredPrimary = savedFlag;
    }
   function _createAndPlaceSlot(
    address user,
    uint8 rank,
    uint256 overrideTargetSlotId,
    uint8 subtreeRoot
) internal {
    uint256 targetSlotId;

    if (overrideTargetSlotId == type(uint256).max) {
        revert("XQoreBTC: sponsor tree full");
    }

    if (overrideTargetSlotId != 0) {
        require(
            _findBFSOpenPosition(overrideTargetSlotId) != 0,
            "XQoreBTC: sponsor slot full"
        );
        targetSlotId = overrideTargetSlotId;
    } else {
        targetSlotId = 0; // no sponsor/global root case only
    }

    UserRankData storage urd = userRankData[user][rank];
    urd.cycleCount++;

    uint256 slotId = nextSlotId++;
    slots[slotId] = MatrixSlot({
        owner: user,
        rank: rank,
        cycle: urd.cycleCount,
        filledCount: 0
    });
    urd.activeSlotId = slotId;
    rankSlotQueue[rank].push(slotId);

    emit SlotActivated(user, rank, slotId, urd.cycleCount);

    if (targetSlotId != 0) {
        uint8 pos;
        if (subtreeRoot != 0) {
            pos = _findBFSOpenInSubtree(targetSlotId, subtreeRoot);
        }
        if (pos == 0) {
            pos = _findBFSOpenPosition(targetSlotId);
        }

        require(pos != 0, "XQoreBTC: no sponsor-tree position");

        uint8 parentPos = MatrixLib.getParent(pos);
        address parentAddr;
        if (parentPos == 0) {
            parentAddr = slots[targetSlotId].owner;
        } else {
            parentAddr = slotPositions[targetSlotId][parentPos];
        }
        slotPlacementParent[slotId] = parentAddr;

        if (parentPos == 0) {
            slotPlacementGrandParent[slotId] = address(0);
        } else {
            uint8 grandPos = MatrixLib.getParent(parentPos);
            if (grandPos == 0) {
                slotPlacementGrandParent[slotId] = slots[targetSlotId].owner;
            } else {
                slotPlacementGrandParent[slotId] = slotPositions[targetSlotId][grandPos];
            }
        }

        _placeInGlobalMatrix(targetSlotId, user, rank, subtreeRoot);
    }
}

    // ════════════════════════════════════════════════════════════════════════
    //                     INTERNAL — MATRIX PLACEMENT
    // ════════════════════════════════════════════════════════════════════════

    function _findGlobalOpenSlot(uint8 rank) internal returns (uint256) {
        uint256[] storage queue = rankSlotQueue[rank];
        uint256 cursor = rankPlacementCursor[rank];
        while (cursor < queue.length) {
            uint256 sid = queue[cursor];
            if (_findBFSOpenPosition(sid) != 0) {
                rankPlacementCursor[rank] = cursor;
                return sid;
            }
            cursor++;
        }
        rankPlacementCursor[rank] = cursor;
        return 0;
    }

 function _resolveSponsorSlot(
    address sponsorAddr,
    uint8 rank
) internal view returns (uint256, uint8) {
    if (sponsorAddr == address(0)) return (0, 0);
    if (!users[sponsorAddr].registered) return (0, 0);

    Placement memory sp = userPlacement[sponsorAddr][rank];

    if (sp.slotId != 0 && sp.position != 0) {
        uint8 openPos = _findBFSOpenInSubtree(sp.slotId, sp.position);
        if (openPos != 0) {
            return (sp.slotId, sp.position);
        }

        uint256 ownSlotId = userRankData[sponsorAddr][rank].activeSlotId;
        if (ownSlotId != 0 && _findBFSOpenPosition(ownSlotId) != 0) {
            return (ownSlotId, 0);
        }

        return (type(uint256).max, 0); // sponsor tree full
    }

    uint256 sponsorOwnSlotId = userRankData[sponsorAddr][rank].activeSlotId;
    if (sponsorOwnSlotId != 0 && _findBFSOpenPosition(sponsorOwnSlotId) != 0) {
        return (sponsorOwnSlotId, 0);
    }

    return (type(uint256).max, 0); // sponsor tree full
}

    function _findBFSOpenPosition(
        uint256 slotId
    ) internal view returns (uint8) {
        MatrixSlot storage slot = slots[slotId];
        if (slot.filledCount >= MatrixLib.MATRIX_SIZE) return 0;

        for (uint8 p = 1; p <= MatrixLib.MATRIX_SIZE; p++) {
            if (slotPositions[slotId][p] != address(0)) continue; // occupied
            uint8 parent = MatrixLib.getParent(p);
            if (parent == 0 || slotPositions[slotId][parent] != address(0)) {
                return p;
            }
        }
        return 0;
    }

    /**
     * @dev Find the first BFS-open position that is a descendant of `ancestor`
     *      in the 3-ary tree. Scans children of ancestor first (Line N+1),
     *      then grandchildren (Line N+2), etc.
     *      Returns 0 if no open descendant position exists.
     */
    function _findBFSOpenInSubtree(
        uint256 slotId,
        uint8 ancestor
    ) internal view returns (uint8) {
        MatrixSlot storage slot = slots[slotId];
        if (slot.filledCount >= MatrixLib.MATRIX_SIZE) return 0;

        // BFS within subtree: scan positions 1..39 in order and check ancestry
        for (uint8 p = 1; p <= MatrixLib.MATRIX_SIZE; p++) {
            if (slotPositions[slotId][p] != address(0)) continue; // occupied
            uint8 parent = MatrixLib.getParent(p);
            // Must have parent occupied (or parent is root)
            if (parent != 0 && slotPositions[slotId][parent] == address(0))
                continue;
            // Check if p is a descendant of ancestor
            if (_isDescendantOf(p, ancestor)) return p;
        }
        return 0;
    }

    /**
     * @dev Check if `pos` is a descendant of `ancestor` in the 3-ary tree.
     *      Walks up from pos to root; returns true if ancestor is found.
     */
    function _isDescendantOf(
        uint8 pos,
        uint8 ancestor
    ) internal pure returns (bool) {
        if (pos == ancestor) return false; // not a descendant of itself
        uint8 cur = pos;
        while (cur > 0) {
            uint8 par = MatrixLib.getParent(cur);
            if (par == ancestor) return true;
            cur = par;
        }
        return false;
    }

    /**
     * @dev Cascade fill: places `user` at `position` in `slotId` and pays the
     *      slot owner based on position color. No ancestor split, no sponsor chain.
     *
     *      GREEN  → owner receives linePercent% of M  (cash transfer)
     *      RED    → owner's recycleBuffer += linePercent% of M  (then _checkRecycle)
     *      YELLOW → owner's upgradeBuffer += linePercent% of M  (then _checkUpgrade)
     *      BLUE   → royal club pool funded
     *
     *      Does NOT update userPlacement — primary placement is the canonical record.
     */
    function _cascadePositionPayout(
        uint256 slotId,
        uint8 position,
        address user,
        uint8 rank
    ) internal {
        slots[slotId].filledCount++;
        slotPositions[slotId][position] = user;
        emit PositionFilled(slotId, position, user);

        address owner = slots[slotId].owner;
        uint32 cycle = slots[slotId].cycle;

        uint256 M = MatrixLib.getMatrixAmount(rank);
        uint256 lineAmt;
        if (position <= 3)
            lineAmt = (M * GREEN_PARENT_BPS) / MatrixLib.BASIS_POINTS; // 20%
        else if (position <= 12)
            lineAmt = (M * GREEN_MIDDLE_BPS) / MatrixLib.BASIS_POINTS; // 30%
        else lineAmt = (M * GREEN_OWNER_BPS) / MatrixLib.BASIS_POINTS; // 50%

        MatrixLib.PositionType posType = MatrixLib.getPositionType(
            position,
            cycle
        );

        if (posType == MatrixLib.PositionType.INCOME) {
            userRankData[owner][rank].totalIncomeEarned += lineAmt;
            if (position <= 3) userRankData[owner][rank].line1Earned += lineAmt;
            else if (position <= 12)
                userRankData[owner][rank].line2Earned += lineAmt;
            else userRankData[owner][rank].line3Earned += lineAmt;
            btcbToken.safeTransfer(owner, lineAmt);
            emit IncomePayout(owner, rank, lineAmt);
        } else if (posType == MatrixLib.PositionType.RECYCLE) {
            userRankData[owner][rank].recycleBuffer += lineAmt;
            userRankData[owner][rank].totalRecycleEarned += lineAmt;
            _checkRecycle(owner, rank);
        } else if (posType == MatrixLib.PositionType.AUTO_UPGRADE) {
            _payAutoUpgrade(owner, rank, lineAmt);
            _checkUpgrade(owner, rank);
        } else {
            _payRoyalClub(lineAmt);
        }
    }

    /**
     * @dev Cascade record-only: places `user` at `position` in `slotId` for
     *      visibility purposes only. No payout of any kind is triggered.
     *
     *      Used for L1 primary fills where _paySponsorChain() has already paid
     *      the sponsor chain (owner.sponsor = 30%, owner.sponsor.sponsor = 50%).
     *      Firing _cascadePositionPayout() on top of that would double-pay those
     *      addresses; we only want the tree visibility, not the extra payout.
     */
    function _cascadeRecordOnly(
        uint256 slotId,
        uint8 position,
        address user
    ) internal {
        slots[slotId].filledCount++;
        slotPositions[slotId][position] = user;
        emit PositionFilled(slotId, position, user);
    }

    function _cascadeVisibility(
        uint256 primarySlotId,
        uint8 primaryPos,
        address user,
        uint8 rank
    ) internal {
        uint8 parentPos = MatrixLib.getParent(primaryPos);
        address slotOwner = slots[primarySlotId].owner;

        address target1;
        address target2;
        bool recordOnly;

        if (parentPos == 0) {
            // ── L1: GREEN → record-only (paySponsorChain already paid)
            //        RED   → color-aware cascade (paySponsorChain is blocked by Fix 1)
            target1 = users[slotOwner].sponsor;
            if (target1 != address(0) && users[target1].registered) {
                target2 = users[target1].sponsor;
            }
            MatrixLib.PositionType posType = MatrixLib.getPositionType(
                primaryPos,
                slots[primarySlotId].cycle
            );
            recordOnly = (posType == MatrixLib.PositionType.INCOME);
        } else {
            // ── L2/L3: cascade via matrix tree-parent (and middle for L3) ──
            address treeParent = slotPositions[primarySlotId][parentPos];
            if (treeParent != address(0) && treeParent != slotOwner) {
                target1 = treeParent;
            }
            if (target1 != address(0)) {
                uint8 grandPos = MatrixLib.getParent(parentPos);
                if (grandPos != 0) {
                    address middle = slotPositions[primarySlotId][grandPos];
                    if (
                        middle != address(0) &&
                        middle != slotOwner &&
                        middle != target1
                    ) {
                        target2 = middle;
                    }
                }
            }
            recordOnly = false;
        }

        // ── Fill target1 ──
        if (target1 != address(0) && users[target1].registered) {
            uint256 t1Slot = userRankData[target1][rank].activeSlotId;
            if (t1Slot != 0 && t1Slot != primarySlotId) {
                uint8 pos;
                if (parentPos == 0) {
                    // Subtree-aware: place under slotOwner's position in target1's slot
                    // so tree depth is preserved (e.g. U11 lands under U1's subtree in U's slot).
                    Placement memory ownerInT1 = userPlacement[slotOwner][rank];
                    if (ownerInT1.slotId == t1Slot && ownerInT1.position != 0) {
                        pos = _findBFSOpenInSubtree(t1Slot, ownerInT1.position);
                    }
                    if (pos == 0) pos = _findBFSOpenPosition(t1Slot); // fallback: plain BFS
                } else {
                    pos = _findBFSOpenPosition(t1Slot);
                }
                if (pos != 0) {
                    if (recordOnly) _cascadeRecordOnly(t1Slot, pos, user);
                    else _cascadePositionPayout(t1Slot, pos, user, rank);
                }
            }
        }

        // ── Fill target2 ──
        if (
            target2 != address(0) &&
            users[target2].registered &&
            target2 != target1
        ) {
            uint256 t2Slot = userRankData[target2][rank].activeSlotId;
            if (t2Slot != 0 && t2Slot != primarySlotId) {
                uint8 pos;
                if (parentPos == 0) {
                    // Subtree-aware: place under target1's position in target2's slot.
                    Placement memory t1InT2 = userPlacement[target1][rank];
                    if (t1InT2.slotId == t2Slot && t1InT2.position != 0) {
                        pos = _findBFSOpenInSubtree(t2Slot, t1InT2.position);
                    }
                    if (pos == 0) pos = _findBFSOpenPosition(t2Slot); // fallback: plain BFS
                } else {
                    pos = _findBFSOpenPosition(t2Slot);
                }
                if (pos != 0) {
                    // target2 (s2) is ALWAYS color-aware — never record-only.
                    // _paySponsorChain only covers s1. s2 was never pre-paid,
                    // so we must always run the full color-aware payout here:
                    // GREEN → cash, RED → recycleBuffer, YELLOW → upgradeBuffer.
                    _cascadePositionPayout(t2Slot, pos, user, rank);
                }
            }
        }
    }

    /**
     * @dev Dual placement: fill sponsor's own slot so they see referrals and earn.
     *      Skipped if sponsor already received ancestor payout (avoid double payment).
     */
    function _fillSponsorOwnSlot(
        address sponsorAddr,
        address user,
        uint8 rank,
        uint256 alreadyUsedSlotId
    ) internal {
        if (sponsorAddr == address(0)) return;
        uint256 sponsorOwnSlotId = userRankData[sponsorAddr][rank].activeSlotId;
        if (sponsorOwnSlotId == 0) return;
        if (sponsorOwnSlotId == alreadyUsedSlotId) return;

        // Skip dual placement when sponsor received ancestor payout AND position is non-green.
        // For yellow/red/blue positions, sponsor gets only ancestor split — no double payment.
        // For green positions, dual placement applies (e.g. A's slot gets A1,B1,C1).
        Placement memory pl = userPlacement[user][rank];
        if (pl.slotId == alreadyUsedSlotId && pl.position != 0) {
            MatrixLib.PositionType pt = MatrixLib.getPositionType(
                pl.position,
                slots[alreadyUsedSlotId].cycle
            );
            if (pt != MatrixLib.PositionType.INCOME) {
                address owner = slots[alreadyUsedSlotId].owner;
                uint8 parentPos = MatrixLib.getParent(pl.position);
                address treeParent = parentPos == 0
                    ? owner
                    : slotPositions[alreadyUsedSlotId][parentPos];
                if (treeParent == sponsorAddr) return;
                if (parentPos != 0) {
                    uint8 grandPos = MatrixLib.getParent(parentPos);
                    if (grandPos != 0) {
                        address middle = slotPositions[alreadyUsedSlotId][
                            grandPos
                        ];
                        if (
                            middle != address(0) &&
                            middle != owner &&
                            middle == sponsorAddr
                        ) return;
                    }
                }
            }
        }

        uint8 pos = _findBFSOpenPosition(sponsorOwnSlotId);
        if (pos == 0) return;

        MatrixSlot storage slot = slots[sponsorOwnSlotId];
        slot.filledCount++;
        slotPositions[sponsorOwnSlotId][pos] = user;

        emit PositionFilled(sponsorOwnSlotId, pos, user);

        _processPositionPayout(sponsorOwnSlotId, pos);
    }

    function _placeInGlobalMatrix(
        uint256 targetSlotId,
        address user,
        uint8 rank,
        uint8 subtreeRoot
    ) internal {
        uint8 position;
        if (subtreeRoot != 0) {
            position = _findBFSOpenInSubtree(targetSlotId, subtreeRoot);
        }
        if (position == 0) {
            position = _findBFSOpenPosition(targetSlotId);
        }
        require(position != 0, "XQoreBTC: no open BFS position");

        MatrixSlot storage slot = slots[targetSlotId];
        slot.filledCount++;
        slotPositions[targetSlotId][position] = user;

        userPlacement[user][rank] = Placement({
            slotId: targetSlotId,
            position: position
        });

        emit PositionFilled(targetSlotId, position, user);

        _processPositionPayout(targetSlotId, position);

        _cascadeVisibilityRecordOnly(targetSlotId, position, user, rank);
    }

    // ════════════════════════════════════════════════════════════════════════
    //                     INTERNAL — PAYOUT DISPATCH
    // ════════════════════════════════════════════════════════════════════════

    function _processPositionPayout(uint256 slotId, uint8 position) internal {
        if (_depth >= MAX_RECURSION) return;
        _depth++;

        MatrixSlot storage slot = slots[slotId];
        address owner = slot.owner;
        uint8 rank = slot.rank;
        uint32 cycle = slot.cycle;

        uint256 payout = MatrixLib.getPayoutAmount(rank, position);
        MatrixLib.PositionType posType = MatrixLib.getPositionType(
            position,
            cycle
        );

        // Track per-line earnings for the slot owner
        if (position <= 3) userRankData[owner][rank].line1Earned += payout;
        else if (position <= 12)
            userRankData[owner][rank].line2Earned += payout;
        else userRankData[owner][rank].line3Earned += payout;

        // Non-owner ancestors always receive their M[rank] income split
        _payAncestors(slotId, position, owner, rank);

        if (posType == MatrixLib.PositionType.INCOME) {
            _payIncomeOwner(slotId, position, owner, rank);
        } else if (posType == MatrixLib.PositionType.RECYCLE) {
            _payRecycle(slotId, position, owner, rank, payout);
        } else if (posType == MatrixLib.PositionType.AUTO_UPGRADE) {
            _payAutoUpgrade(owner, rank, payout);
        } else {
            _payRoyalClub(payout);
        }

        _checkRecycle(owner, rank);
        _checkUpgrade(owner, rank);

        _depth--;
    }

    // ──────── Ancestor Income (runs for ALL position types) ────────

    // Non-owner ancestors always receive their share of M[rank]:
    //   tree-parent  (if ≠ owner) → 20% of M[rank]
    //   middle ancestor (if exists & ≠ owner) → 30% of M[rank]
    // If tree-parent IS the owner, no ancestor payout (handled by green owner logic).
    uint256 internal constant GREEN_PARENT_BPS = 2_000; // 20 % of M[rank]
    uint256 internal constant GREEN_MIDDLE_BPS = 3_000; // 30 % of M[rank]
    uint256 internal constant GREEN_OWNER_BPS = 5_000; // 50 % of M[rank]

    // @dev Pays s1 (owner.sponsor) their 30% M share for a GREEN L1 primary fill.
    // s2 is NOT paid here — handled by _cascadeVisibility target2 which is
    // fully color-aware (GREEN=cash, RED=recycleBuffer, YELLOW=upgradeBuffer).
    function _paySponsorChain(address owner, uint8 rank) internal {
        uint256 M = MatrixLib.getMatrixAmount(rank);
        address s1 = users[owner].sponsor;
        if (s1 == address(0) || !users[s1].registered) return;

        uint256 amt1 = (M * GREEN_MIDDLE_BPS) / MatrixLib.BASIS_POINTS;
        btcbToken.safeTransfer(s1, amt1);
        userRankData[s1][rank].totalIncomeEarned += amt1;
        userRankData[s1][rank].line1Earned += amt1;
        emit IncomePayout(s1, rank, amt1);

        // s2 is handled by _cascadeVisibility (target2) — color-aware.
        // Do NOT pay s2 here.
    }

    event IncomePayoutSplit(
        address indexed owner,
        address indexed treeParent,
        address indexed middleAncestor,
        uint8 rank,
        uint256 ownerAmt,
        uint256 parentAmt,
        uint256 middleAmt
    );

    function _payAncestors(
        uint256 slotId,
        uint8 position,
        address owner,
        uint8 rank
    ) internal {
        uint8 parentPos = MatrixLib.getParent(position);
        address treeParent = (parentPos == 0)
            ? owner
            : slotPositions[slotId][parentPos];

        // ── L1 fill: tree-parent IS the owner ──
        // Pay sponsor chain ONLY for GREEN (INCOME) positions.
        // RED pos3 must not send cash up the sponsor chain —
        // recycleBuffer is credited by _payRecycle instead.
        if (treeParent == address(0) || treeParent == owner) {
            MatrixLib.PositionType posType = MatrixLib.getPositionType(
                position,
                slots[slotId].cycle
            );
            if (posType == MatrixLib.PositionType.INCOME) {
                _paySponsorChain(owner, rank);
            }
            return;
        }

        // ── L2/L3 fill: tree-parent is a different user ──
        // Suppress only for sponsored primary registrations, where tree-parent's
        // own slot will receive a cascade fill. For global BFS / upgrades /
        // recycles, cascade is not responsible for ancestor income.
        uint256 treeParentSlot = userRankData[treeParent][rank].activeSlotId;
        if (treeParentSlot != 0 && _isSponsoredPrimary) {
            return; // cascade will handle income via tree-parent's own slot
        }

        // ── Tree-parent has NO own slot: pay ancestor split normally ──
        uint256 M = MatrixLib.getMatrixAmount(rank);
        uint256 parentAmt = (M * GREEN_PARENT_BPS) / MatrixLib.BASIS_POINTS; // 20%
        btcbToken.safeTransfer(treeParent, parentAmt);
        userRankData[treeParent][rank].totalIncomeEarned += parentAmt;
        if (position <= 3)
            userRankData[treeParent][rank].line1Earned += parentAmt;
        else if (position <= 12)
            userRankData[treeParent][rank].line2Earned += parentAmt;
        else userRankData[treeParent][rank].line3Earned += parentAmt;

        uint256 middleAmt = 0;
        address middleAncestor = address(0);
        if (parentPos != 0) {
            uint8 grandPos = MatrixLib.getParent(parentPos);
            if (grandPos != 0) {
                address gp = slotPositions[slotId][grandPos];
                if (gp != address(0) && gp != owner) {
                    middleAncestor = gp;
                    middleAmt = (M * GREEN_MIDDLE_BPS) / MatrixLib.BASIS_POINTS; // 30%
                    btcbToken.safeTransfer(middleAncestor, middleAmt);
                    userRankData[middleAncestor][rank]
                        .totalIncomeEarned += middleAmt;
                    if (position <= 3)
                        userRankData[middleAncestor][rank]
                            .line1Earned += middleAmt;
                    else if (position <= 12)
                        userRankData[middleAncestor][rank]
                            .line2Earned += middleAmt;
                    else
                        userRankData[middleAncestor][rank]
                            .line3Earned += middleAmt;
                }
            }
        }

        emit IncomePayoutSplit(
            owner,
            treeParent,
            middleAncestor,
            rank,
            0,
            parentAmt,
            middleAmt
        );
    }

    // ──────── Green (Income) — owner share only ────────

    function _payIncomeOwner(
        uint256 slotId,
        uint8 position,
        address owner,
        uint8 rank
    ) internal {
        uint256 M = MatrixLib.getMatrixAmount(rank);

        uint8 parentPos = MatrixLib.getParent(position);
        address treeParent;
        if (parentPos == 0) {
            treeParent = owner;
        } else {
            treeParent = slotPositions[slotId][parentPos];
        }

        uint256 ownerAmt;
        if (treeParent == address(0) || treeParent == owner) {
            ownerAmt = (M * GREEN_PARENT_BPS) / MatrixLib.BASIS_POINTS; // 20%
        } else {
            // Check if middle ancestor exists
            bool hasMiddle = false;
            if (parentPos != 0) {
                uint8 grandPos = MatrixLib.getParent(parentPos);
                if (grandPos != 0) {
                    address gp = slotPositions[slotId][grandPos];
                    if (gp != address(0) && gp != owner) hasMiddle = true;
                }
            }
            ownerAmt = hasMiddle
                ? (M * GREEN_OWNER_BPS) / MatrixLib.BASIS_POINTS // 50%
                : (M * 3_000) / MatrixLib.BASIS_POINTS; // 30%
        }

        userRankData[owner][rank].totalIncomeEarned += ownerAmt;
        btcbToken.safeTransfer(owner, ownerAmt);
        emit IncomePayout(owner, rank, ownerAmt);
    }

    // ──────── Red (Recycle) ────────

    /**
     * @dev Red payout uses **tree-positional** parent/grandparent of the red
     *      position within the slot's 3-ary tree, not the slot's global lineage.
     *      - parent  = address at the parent node of `position` in this slot
     *      - parent2 = address at the grandparent node (parent of parent)
     *      Root (position 0) is the slot owner.
     */
    function _payRecycle(
        uint256 slotId,
        uint8 position,
        address owner,
        uint8 rank,
        uint256 payout
    ) internal {
        // Resolve tree-positional parent
        uint8 parentPos = MatrixLib.getParent(position);
        address sponsor;
        if (parentPos == 0) {
            sponsor = owner; // parent is root = slot owner
        } else {
            sponsor = slotPositions[slotId][parentPos];
        }

        // Resolve tree-positional grandparent
        address sponsor2;
        if (parentPos == 0) {
            sponsor2 = address(0); // root has no grandparent
        } else {
            uint8 grandPos = MatrixLib.getParent(parentPos);
            if (grandPos == 0) {
                sponsor2 = owner; // grandparent is root = slot owner
            } else {
                sponsor2 = slotPositions[slotId][grandPos];
            }
        }

        // Red amounts go to recycle buffer only — no BTCB transfers
        userRankData[owner][rank].recycleBuffer += payout;
        userRankData[owner][rank].totalRecycleEarned += payout;

        emit RecyclePayout(owner, sponsor, sponsor2, rank, 0, 0, 0);
    }

    // ──────── Yellow (Auto-Upgrade) ────────

    function _payAutoUpgrade(
        address owner,
        uint8 rank,
        uint256 amount
    ) internal {
        if (rank == MatrixLib.MAX_RANK) {
            userRankData[owner][rank].totalIncomeEarned += amount;
            btcbToken.safeTransfer(owner, amount);
            emit IncomePayout(owner, rank, amount);
            return;
        }
        userRankData[owner][rank].upgradeBuffer += amount;
        userRankData[owner][rank].totalUpgradeRouted += amount;
    }

    // ──────── Blue (Royal Club) ────────

    function _payRoyalClub(uint256 amount) internal {
        RoyalClubLib.fundPool(_royalClub, amount);
        emit RoyalClubFunded(amount);
    }

    // ════════════════════════════════════════════════════════════════════════
    //                   INTERNAL — RECYCLE & UPGRADE TRIGGERS
    // ════════════════════════════════════════════════════════════════════════

    // function _checkRecycle(address owner, uint8 rank) internal {
    //     UserRankData storage urd = userRankData[owner][rank];
    //     uint256 matrixAmt = MatrixLib.getMatrixAmount(rank);

    //     if (urd.recycleBuffer >= matrixAmt) {
    //         urd.recycleBuffer -= matrixAmt;

    //         uint32 newCycle = urd.cycleCount + 1;
    //         emit RecycleTriggered(owner, rank, newCycle);

    //         _recycleSlot(owner, rank);
    //     }
    // }
    function _checkRecycle(address owner, uint8 rank) internal {
        UserRankData storage urd = userRankData[owner][rank];
        uint256 activeSlotId = urd.activeSlotId;

        if (activeSlotId == 0) return;

        if (slots[activeSlotId].filledCount < MatrixLib.MATRIX_SIZE) {
            return;
        }

        uint256 matrixAmt = MatrixLib.getMatrixAmount(rank);

        if (urd.recycleBuffer >= matrixAmt) {
            urd.recycleBuffer -= matrixAmt;

            uint32 newCycle = urd.cycleCount + 1;
            emit RecycleTriggered(owner, rank, newCycle);

            _recycleSlot(owner, rank);
        }
    }

    function _checkUpgrade(address owner, uint8 rank) internal {
        if (rank >= MatrixLib.MAX_RANK) return;

        UserRankData storage urd = userRankData[owner][rank];
        uint8 nextRank = rank + 1;
        if (isRankActive(owner, nextRank)) return;
        uint256 nextPrice = MatrixLib.getRankPrice(nextRank);

        if (urd.upgradeBuffer >= nextPrice) {
            urd.upgradeBuffer -= nextPrice;

            emit UpgradeTriggered(owner, rank, nextRank);

            // Upgrades are always global BFS — never a sponsored primary placement.
            // Save and clear the flag so _payAncestors behaves correctly inside the
            // nested _activateRank, then restore for the outer context.
            bool savedFlag = _isSponsoredPrimary;
            _isSponsoredPrimary = false;
            // _activateRank(owner, nextRank, 0, 0); // upgrades always use global placement
            _activateRank(owner, nextRank);
            _isSponsoredPrimary = savedFlag;
        }
    }

    // ════════════════════════════════════════════════════════════════════════
    //                   INTERNAL — REFERRAL COUNTERS
    // ════════════════════════════════════════════════════════════════════════

    /**
     * @dev Walk up the sponsor chain and increment counters.
     *      The immediate sponsor gets both directCount++ and teamCount++,
     *      and msg.sender is appended to their _directReferrals array.
     *      Every ancestor above only gets teamCount++.
     *      Loop terminates at address(0) or an unregistered address.
     */
    function _incrementSponsorCounts(address sponsorAddr) internal {
        address cur = sponsorAddr;
        bool isDirect = true;
        while (cur != address(0) && users[cur].registered) {
            if (isDirect) {
                users[cur].directCount++;
                _directReferrals[cur].push(msg.sender);
                isDirect = false;
            }
            users[cur].teamCount++;
            cur = users[cur].sponsor;
        }
    }

    function _resolveSponsorfromUsername(
        string calldata sponsorUsername
    ) internal view returns (address) {
        if (bytes(sponsorUsername).length == 0) return address(0);

        if (
            keccak256(bytes(sponsorUsername)) == keccak256(bytes(adminUsername))
        ) {
            return shareAddress1;
        }

        // Look up the address; returns address(0) if not registered yet
        return usernameToAddress[sponsorUsername];
    }

    // ════════════════════════════════════════════════════════════════════════
    //                   INTERNAL — USERNAME VALIDATION
    // ════════════════════════════════════════════════════════════════════════

    /**
     * @dev Alphanumeric only, length 3–20. Calldata version used in register().
     */
    function _isValidUsername(
        string calldata username
    ) internal pure returns (bool) {
        bytes calldata b = bytes(username);
        if (b.length < 3 || b.length > 20) return false;
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            if (
                !(c >= 0x30 && c <= 0x39) && // 0-9
                !(c >= 0x41 && c <= 0x5A) && // A-Z
                !(c >= 0x61 && c <= 0x7A) // a-z
            ) return false;
        }
        return true;
    }

    /**
     * @dev Memory version used in the constructor for the adminUsername.
     */
    function _isValidUsernameMemory(
        string memory username
    ) internal pure returns (bool) {
        bytes memory b = bytes(username);
        if (b.length < 3 || b.length > 20) return false;
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            if (
                !(c >= 0x30 && c <= 0x39) &&
                !(c >= 0x41 && c <= 0x5A) &&
                !(c >= 0x61 && c <= 0x7A)
            ) return false;
        }
        return true;
    }
function _resolvePlacementTarget(
    address user,
    uint8 rank
) internal view returns (uint256 targetSlotId, uint8 subtreeRoot) {
    address sponsorAddr = users[user].sponsor;
    address topSponsor;

    while (sponsorAddr != address(0) && users[sponsorAddr].registered) {
        topSponsor = sponsorAddr;

        (uint256 slotId, uint8 subRoot) = _resolveSponsorSlot(sponsorAddr, rank);
        if (slotId != 0 && slotId != type(uint256).max) {
            return (slotId, subRoot);
        }

        sponsorAddr = users[sponsorAddr].sponsor;
    }

    require(topSponsor != address(0), "XQoreBTC: invalid sponsor chain");

    uint256 rootSlot = userRankData[topSponsor][rank].activeSlotId;
    require(rootSlot != 0, "XQoreBTC: top sponsor has no active slot");

    uint8 pos = _findBFSOpenPosition(rootSlot);
    require(pos != 0, "XQoreBTC: all sponsor trees full");

    return (rootSlot, 0);
}



    function _cascadeVisibilityRecordOnly(
        uint256 primarySlotId,
        uint8 primaryPos,
        address user,
        uint8 rank
    ) internal {
        uint8 parentPos = MatrixLib.getParent(primaryPos);
        address slotOwner = slots[primarySlotId].owner;

        address target1;
        address target2;

        if (parentPos == 0) {
            target1 = users[slotOwner].sponsor;
            if (target1 != address(0) && users[target1].registered) {
                target2 = users[target1].sponsor;
            }
        } else {
            address treeParent = slotPositions[primarySlotId][parentPos];
            if (treeParent != address(0) && treeParent != slotOwner) {
                target1 = treeParent;
            }

            if (target1 != address(0)) {
                uint8 grandPos = MatrixLib.getParent(parentPos);
                if (grandPos != 0) {
                    address middle = slotPositions[primarySlotId][grandPos];
                    if (
                        middle != address(0) &&
                        middle != slotOwner &&
                        middle != target1
                    ) {
                        target2 = middle;
                    }
                }
            }
        }

        if (target1 != address(0) && users[target1].registered) {
            uint256 t1Slot = userRankData[target1][rank].activeSlotId;
            if (t1Slot != 0 && t1Slot != primarySlotId) {
                uint8 pos;
                if (parentPos == 0) {
                    Placement memory ownerInT1 = userPlacement[slotOwner][rank];
                    if (ownerInT1.slotId == t1Slot && ownerInT1.position != 0) {
                        pos = _findBFSOpenInSubtree(t1Slot, ownerInT1.position);
                    }
                    if (pos == 0) pos = _findBFSOpenPosition(t1Slot);
                } else {
                    pos = _findBFSOpenPosition(t1Slot);
                }

                if (pos != 0) {
                    _cascadeRecordOnly(t1Slot, pos, user);
                }
            }
        }

        if (
            target2 != address(0) &&
            users[target2].registered &&
            target2 != target1
        ) {
            uint256 t2Slot = userRankData[target2][rank].activeSlotId;
            if (t2Slot != 0 && t2Slot != primarySlotId) {
                uint8 pos;
                if (parentPos == 0) {
                    Placement memory t1InT2 = userPlacement[target1][rank];
                    if (t1InT2.slotId == t2Slot && t1InT2.position != 0) {
                        pos = _findBFSOpenInSubtree(t2Slot, t1InT2.position);
                    }
                    if (pos == 0) pos = _findBFSOpenPosition(t2Slot);
                } else {
                    pos = _findBFSOpenPosition(t2Slot);
                }

                if (pos != 0) {
                    _cascadeRecordOnly(t2Slot, pos, user);
                }
            }
        }
    }
